import{_ as p,o as t,c as e,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const i=JSON.parse('{"title":"Stub的影响","description":"","frontmatter":{},"headers":[],"relativePath":"notes/《信号完整性》学习笔记/22-Stub的影响.md","filePath":"notes/《信号完整性》学习笔记/22-Stub的影响.md","lastUpdated":1794320584000}'),c={name:"notes/《信号完整性》学习笔记/22-Stub的影响.md"};function r(n,a,l,d,o,b){return t(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="stub的影响" tabindex="-1">Stub的影响 <a class="header-anchor" href="#stub的影响" aria-label="Permalink to &quot;Stub的影响&quot;">​</a></h1><p>感性负载和容性负载的分析思路基本上是一样的，两者好像是一对对偶结构，作用刚好相反。</p><h2 id="一分支点的负反射" tabindex="-1">一、分支点的负反射 <a class="header-anchor" href="#一分支点的负反射" aria-label="Permalink to &quot;一、分支点的负反射&quot;">​</a></h2><p>链路中间、末端负载之前有一个分支，会让末端接收到的信号波形变得比较乱，因为在分支这个位置会发生反射。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794302510360-70460add-9dff-4677-aaf7-c3e62a879df7.svg" alt="有分支的互连结构"></p><p>信号到分支点的瞬间，感受到的是两个 50 Ω 传输线并联，阻抗突然间降低，就会发生负反射。</p><p>信号到达半幅度以后，这个半幅度经过一段时间过来，在分支点突然间产生一个负反射；负反射回来叠加在入射信号上，出现一个小的凹陷。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794295959944-3f060bc1-2b72-4b99-b0df-acb78072fd3a.svg" alt="传输线入口的波形"></p><p>这就证明信号到分支点之后感受到阻抗突然降低，产生了负反射。</p><p>信号到达末端，末端是高阻抗，发生反射。反射信号回到分支点，又发生一次负反射；再回到末端，叠加在末端波形上，出来一个小的塌陷。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794295960488-f4065042-2881-4cfb-b289-18ba407240f2.svg" alt="末端的波形"></p><p>有分支的结构会让两侧的信号波形噪声都变大，因为信号每到分支点都会发生负反射。</p><h2 id="二分支长度与反射噪声" tabindex="-1">二、分支长度与反射噪声 <a class="header-anchor" href="#二分支长度与反射噪声" aria-label="Permalink to &quot;二、分支长度与反射噪声&quot;">​</a></h2><p>分支结构的影响跟分支的长度有关。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794307577644-c8107d33-cd04-4bae-b372-3db507435e8e.svg" alt="分支长度的仿真结构"></p><p>入射信号的上升时间都是 300 ps，分支机构都是 50 Ω 特性阻抗。</p><p>分支的长度用延时来衡量：15ps 是信号上升时间的 5%，60 ps 是信号上升时间的 20%，150 ps 是信号上升时间的 50%。</p><p>近端看红色这条线：分支长度对应的延时是信号上升时间的 5% 时，波形还不错，有一点噪声，但噪声比较小。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794311115818-c28408c1-68bc-4a04-b2b1-9192dd44319a.svg" alt="分支长度不同时的近端波形"></p><p>末端也是有一点噪声，噪声比较小，有一点塌陷。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794312089422-a3c219b8-23c9-4e80-96a9-5790db9a1252.svg" alt="分支长度不同时的末端波形"></p><p>分支长度对应的延时是信号上升时间的 50% 时，近端波形的反射噪声比较大，末端波形的反射噪声也比较大。</p><p>反射到底能有多大、对信号波形造成的恶劣影响到底有多严重，跟分支的长度有关。分支越长，反射就会越厉害。</p><h2 id="三fly-by-结构与短分支" tabindex="-1">三、Fly-by 结构与短分支 <a class="header-anchor" href="#三fly-by-结构与短分支" aria-label="Permalink to &quot;三、Fly-by 结构与短分支&quot;">​</a></h2><p>信号速率比较高的时候，如果能用 Fly-by，尽量用 Fly-by 结构，它的分支非常非常短。</p><p>比如 DDR 地址线用 Fly-by 结构，线基本都拉到芯片管脚下面，直接连到扇出过孔上。</p><p>这些扇出过孔之间那一小段很短，就相当于分支非常短，有利于改善芯片的波形质量。</p><p>分支的长度对比的是信号的上升时间，信号上升时间比较快的时候，容许的分支长度就比较小。</p><h2 id="四驱动器上升时间与分支长度" tabindex="-1">四、驱动器上升时间与分支长度 <a class="header-anchor" href="#四驱动器上升时间与分支长度" aria-label="Permalink to &quot;四、驱动器上升时间与分支长度&quot;">​</a></h2><p>同样的分支长度，如果驱动器的信号上升时间比较长，比如 2000 ps 也就是 2 ns，驱动器变化比较缓慢，接收端信号波形的质量要好得多。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794316735989-8b5acd39-32d9-4107-a827-22de1a235853.svg" alt="信号上升时间 2 ns 时的波形"></p><p>驱动器的上升时间不同，能容忍的分支长度也不一样。</p><p>上升时间 1000 ps，也就是 1 ns 时，比 300 ps 的时候要好；</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794318444383-a467a316-b08a-47ee-8c21-e0bae4273615.svg" alt="信号上升时间 1 ns 时的波形"></p><p>进一步减小到 100 ps，波形就搞得特别的乱。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794319961836-4ce66272-0489-4d56-80ce-205cf8f5c09a.svg" alt="信号上升时间 100 ps 时的波形"></p><p>分支能容忍的长度和驱动器特性有关，和驱动信号的上升时间有关。</p><p>总之，就是一个趋势：分支越长，信号质量可能就会越差。</p>',38)])])}const h=p(c,[["render",r]]);export{i as __pageData,h as default};
